import Button from 'flarum/common/components/Button';
import { extend } from 'flarum/common/extend';
import app from 'flarum/forum/app';
import PostControls from 'flarum/forum/utils/PostControls';
import canModerateCommunityNotes from '../utils/canModerateCommunityNotes';
export default function addPostControls(open, manage) {
  extend(PostControls, 'userControls', (items, post) => {
    if (!app.session.user || post.contentType() !== 'comment') return;
    const author = post.user();
    // 字段缺失时等待完整 Post 响应，不根据残缺 Store 数据猜测资格。
    const ownId = post.attribute('myCommunityNoteId');
    if (app.forum.canCreateCommunityNotes() && !post.isHidden() && (!author || author.id() !== app.session.user.id()) && ownId !== undefined) {
      items.add('communityNote', m(Button, {
        icon: "far fa-note-sticky",
        onclick: () => open(post)
      }, ownId ? app.translator.trans('ffans-community-notes.forum.post_controls.view_mine_button', {}, true) : app.translator.trans('ffans-community-notes.forum.post_controls.add_button', {}, true)));
    }

    // 同一原生菜单分组内紧随添加入口，管理资格不依赖创建资格或帖子作者身份。
    if (canModerateCommunityNotes() && (post.attribute('communityNoteCount') || 0) > 0) {
      items.add('manageCommunityNotes', m(Button, {
        icon: "fas fa-shield-halved",
        onclick: () => manage(post)
      }, app.translator.trans('ffans-community-notes.forum.post_controls.manage_button')), items.has('communityNote') ? items.getPriority('communityNote') : 0);
    }
  });
}
flarum.reg.add('ffans-community-notes', 'forum/extenders/addPostControls', addPostControls);