import Model from 'flarum/common/Model';
export default class CommunityNote extends Model {
  reason = (() => Model.attribute('reason'))();
  content = (() => Model.attribute('content'))();
  status = (() => Model.attribute('status'))();
  ratingCount = (() => Model.attribute('ratingCount'))();
  score = (() => Model.attribute('score'))();
  sources = (() => Model.attribute('sources'))();
  isMine = (() => Model.attribute('isMine'))();
  isHidden = (() => Model.attribute('isHidden'))();
  hiddenReason = (() => Model.attribute('hiddenReason'))();
  myRating = (() => Model.attribute('myRating'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  post = (() => Model.hasOne('post'))();
  user = (() => Model.hasOne('user'))();
}
flarum.reg.add('ffans-community-notes', 'forum/models/CommunityNote', CommunityNote);