import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import app from 'flarum/forum/app';
export default class CommunityNotePostLink extends Component {
  view() {
    const post = this.attrs.post;
    const discussion = post.discussion();
    if (!discussion) return null;
    const number = post.number();
    const link = m(Link, {
      href: app.route.post(post),
      "aria-label": number > 0 ? app.translator.trans('ffans-community-notes.forum.post_link.with_number_a11y_label', {
        title: discussion.title(),
        number
      }, true) : app.translator.trans('ffans-community-notes.forum.post_link.a11y_label', {
        title: discussion.title()
      }, true)
    }, discussion.title());
    return m("div", {
      className: "CommunityNotePostLink"
    }, this.attrs.heading ? m("h3", null, link, number > 0 && m("span", {
      className: "CommunityNotePostLink-floor",
      "aria-hidden": "true"
    }, app.translator.trans('ffans-community-notes.forum.post_link.number', {
      number
    }))) : link);
  }
}
flarum.reg.add('ffans-community-notes', 'forum/components/CommunityNotePostLink', CommunityNotePostLink);