import Modal from 'flarum/common/components/Modal';
import app from 'flarum/forum/app';
import CommunityNotesState from '../states/CommunityNotesState';
import canViewCommunityNotes from '../utils/canViewCommunityNotes';
import CommunityNotesPostContent from './CommunityNotesPostContent';
export default class CommunityNotesPostModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    this.notesState = new CommunityNotesState({
      post: this.attrs.post.id()
    });
    if (canViewCommunityNotes()) void this.notesState.load();
  }
  className() {
    return 'CommunityNotesPostModal Modal--large';
  }
  title() {
    return app.translator.trans('ffans-community-notes.forum.post.modal_title', {}, true);
  }
  content() {
    return m("div", {
      className: "Modal-body CommunityNotesPage CommunityNotesPage--cards CommunityNotesPage--detail"
    }, m(CommunityNotesPostContent, {
      state: this.notesState,
      post: this.attrs.post
    }));
  }
}
flarum.reg.add('ffans-community-notes', 'forum/components/CommunityNotesPostModal', CommunityNotesPostModal);