import Component from 'flarum/common/Component';
import CommunityNoteSources from './CommunityNoteSources';
export default class CommunityNoteBody extends Component {
  view() {
    const note = this.attrs.note;
    return m("div", {
      className: 'CommunityNote-body ' + this.attrs.className
    }, m("p", {
      className: "CommunityNote-content"
    }, note.content()), m(CommunityNoteSources, {
      sources: note.sources() || []
    }));
  }
}
flarum.reg.add('ffans-community-notes', 'forum/components/CommunityNoteBody', CommunityNoteBody);